import fs from "node:fs";
import path from "node:path";
import { pathToFileURL } from "node:url";
import { filesUnder, loadDataModule, readUsageModel, repositoryRoot, translate, ts } from "./usage-reference-model.mjs";

const generatedNotice =
  "<!-- Generated by scripts/generate-usage-reference.mjs. Edit the source, then regenerate. -->\n\n";
const cell = (value) => String(value).replaceAll("|", "\\|").replaceAll("\n", " ");
const table = (headers, rows) => {
  const formattedHeaders = headers.map(cell);
  const formattedRows = rows.map((row) => row.map(cell));
  const widths = formattedHeaders.map((header, index) =>
    Math.max(header.length, ...formattedRows.map((row) => (row[index] ?? "").length)),
  );
  const formatRow = (values) => `| ${values.map((value, index) => value.padEnd(widths[index])).join(" | ")} |`;
  return [
    formatRow(formattedHeaders),
    `| ${widths.map((width) => "-".repeat(width)).join(" | ")} |`,
    ...formattedRows.map(formatRow),
    "",
  ].join("\n");
};
const sourceFile = (file) => ts.createSourceFile(file, fs.readFileSync(file, "utf8"), ts.ScriptTarget.Latest, true);

function gameSettings(root) {
  const modelPath = "application/shared/game/index.ts";
  const sharedGame = sourceFile(path.join(root, modelPath));
  const defaultsDeclaration = sharedGame.statements
    .flatMap((statement) => (ts.isVariableStatement(statement) ? [...statement.declarationList.declarations] : []))
    .find((declaration) => declaration.name.getText(sharedGame) === "PLAYABLE_CONTENT_DEFAULTS");
  const defaultsInitializer =
    defaultsDeclaration?.initializer && ts.isAsExpression(defaultsDeclaration.initializer)
      ? defaultsDeclaration.initializer.expression
      : defaultsDeclaration?.initializer;
  if (!defaultsInitializer || !ts.isObjectLiteralExpression(defaultsInitializer)) {
    throw new Error("Cannot extract shared playable content defaults.");
  }
  const values = Object.fromEntries(
    defaultsInitializer.properties
      .filter(ts.isPropertyAssignment)
      .map((property) => [property.name.getText(sharedGame), property.initializer.getText(sharedGame)]),
  );
  const rows = [];
  for (const kind of ["quiz", "prediction"]) {
    const inputPath = `application/backend/src/presentation/game/types/${kind}/graphql/types/${kind}-inputs.ts`;
    const source = sourceFile(path.join(root, inputPath));
    const input = source.statements.find(
      (node) =>
        ts.isClassDeclaration(node) &&
        node.name?.text === (kind === "quiz" ? "CreateQuizQuestionInput" : "CreatePredictionPromptInput"),
    );
    for (const field of ["timeLimit", "points"]) {
      const member = input?.members.find((node) => node.name?.getText(source) === field);
      const minimum =
        member &&
        ts
          .getDecorators(member)
          ?.map((decorator) => decorator.expression)
          .find((expression) => ts.isCallExpression(expression) && expression.expression.getText(source) === "Min");
      if (!minimum || !values[field]) throw new Error(`Cannot extract ${kind} ${field} bounds/default.`);
      rows.push([kind, field, values[field], minimum.arguments[0].getText(source), inputPath]);
    }
  }
  return { modelPath, rows };
}

function permissionsFor(declaration, source) {
  let type = declaration.type;
  if (ts.isInterfaceDeclaration(declaration))
    return declaration.members.map((member) => {
      const permission = member.type;
      if (!permission || !ts.isTypeReferenceNode(permission) || permission.typeName.getText(source) !== "ActionPermission")
        throw new Error(`Cannot extract permission reason: ${declaration.name.text}`);
      return [member.name.getText(source), permission.typeArguments[0].getText(source)];
    });
  if (ts.isTypeReferenceNode(type) && type.typeName.getText(source) === "Permissions") type = type.typeArguments[0];
  if (ts.isTypeLiteralNode(type))
    return type.members.map((member) => [member.name.getText(source), member.type.getText(source)]);
  if (ts.isTypeReferenceNode(type) && type.typeName.getText(source) === "Record") {
    const actions = type.typeArguments[0];
    return (ts.isUnionTypeNode(actions) ? actions.types : [actions]).map((action) => [
      action.literal.text,
      type.typeArguments[1].getText(source),
    ]);
  }
  throw new Error(`Cannot extract permission actions: ${declaration.name.text}`);
}

export function generateUsageReference(root = repositoryRoot, check = false) {
  const { guides, resources } = readUsageModel(root);
  const output = new Map();
  const domainPath = "application/backend/src/domain";
  const domain = path.join(root, domainPath);
  const partyPath = "application/shared/party/index.ts";
  const party = loadDataModule(path.join(root, partyPath));
  const gameTypePath = "application/shared/game/index.ts";
  const gameTypes = Object.entries(loadDataModule(path.join(root, gameTypePath)).GameType);
  const sharedErrorsPath = "application/shared/errors/index.ts";
  const sharedErrors = loadDataModule(path.join(root, sharedErrorsPath));
  const sharedPartyPath = "application/shared/party/index.ts";
  const sharedParty = loadDataModule(path.join(root, sharedPartyPath));
  const editor = gameSettings(root);
  const enums = [];
  const permissions = [];
  for (const file of filesUnder(domain).filter((file) => file.endsWith(".ts") && !file.endsWith(".spec.ts"))) {
    const source = sourceFile(file);
    const relative = path.relative(root, file);
    for (const declaration of source.statements) {
      if (ts.isEnumDeclaration(declaration) && /ErrorCode$/.test(declaration.name.text)) {
        for (const member of declaration.members) {
          if (!member.initializer || !ts.isStringLiteral(member.initializer))
            throw new Error(`Non-literal error code: ${file}`);
          enums.push([declaration.name.text, `\`${member.initializer.text}\``, relative]);
        }
      }
      if (
        (ts.isTypeAliasDeclaration(declaration) || ts.isInterfaceDeclaration(declaration)) &&
        /Permissions$/.test(declaration.name.text) &&
        !relative.includes("/domain/shared/")
      ) {
        for (const [action, reason] of permissionsFor(declaration, source))
          permissions.push([declaration.name.text, `\`${action}\``, `\`${reason}\``, relative]);
      }
    }
  }
  for (const [name, values] of Object.entries(sharedErrors)) {
    if (!name.endsWith("ErrorCode") || typeof values !== "object" || values === null) continue;
    for (const code of Object.values(values)) enums.push([name, `\`${code}\``, sharedErrorsPath]);
  }
  for (const action of sharedParty.HOST_PARTY_PERMISSION_ACTIONS) {
    permissions.push(["HostPartyPermissions", `\`${action}\``, "`HostPartyDisabledReason`", sharedPartyPath]);
  }
  if (!enums.length || !permissions.length) throw new Error("Missing permission or error-code sources.");
  for (const locale of ["en", "fr"]) {
    const t = (key) => translate(resources, locale, key);
    const label = (key) => t(`shared.guide.docs.${key}`);
    const prefix = locale === "en" ? "" : "fr/";
    const rootRelative = locale === "en" ? "../../../" : "../../../../";
    const sourceLink = (file) => `[${path.basename(file)}](${rootRelative}${file})`;
    const withSources = (rows) => rows.map((row) => [...row.slice(0, -1), sourceLink(row.at(-1))]);
    output.set(
      `${prefix}generated/settings.md`,
      generatedNotice +
        `# ${label("settings")}\n\n` +
        sourceLink(partyPath) +
        "\n\n" +
        table(
          [label("setting"), label("default"), label("allowed")],
          Object.entries(party.DEFAULT_PARTY_SETTINGS).map(([name, value]) => [
            `\`${name}\``,
            `\`${value}\``,
            typeof value === "boolean"
              ? "`true`, `false`"
              : `${party.PARTY_READING_TIME_LIMITS.min} - ${party.PARTY_READING_TIME_LIMITS.max} (${label("seconds")})`,
          ]),
        ) +
        `\n## ${label("gameSettings")}\n\n${sourceLink(editor.modelPath)}\n\n` +
        table(
          [label("domain"), label("setting"), label("default"), label("minimum"), label("source")],
          withSources(editor.rows),
        ),
    );
    output.set(
      `${prefix}generated/errors.md`,
      generatedNotice +
        `# ${label("errors")}\n\n` +
        table([label("domain"), label("code"), label("source")], withSources(enums)),
    );
    output.set(
      `${prefix}generated/permissions.md`,
      generatedNotice +
        `# ${label("permissions")}\n\n` +
        table([label("domain"), label("action"), label("reason"), label("source")], withSources(permissions)),
    );
    output.set(
      `${prefix}generated/game-types.md`,
      generatedNotice +
        `# ${label("types")}\n\n${sourceLink(gameTypePath)}\n\n` +
        table([label("name"), label("value")], gameTypes),
    );
    for (const guide of guides) {
      const relative = locale === "en" ? "" : "../";
      let markdown = generatedNotice + `# ${t(guide.titleKey)}\n\n`;
      markdown += `[${label("index")}](${relative}index.md) | [${translate(resources, locale === "en" ? "fr" : "en", "shared.guide.docs.language")}](${locale === "en" ? "fr/" : "../"}${guide.docPath})\n\n${label("launchHelp")}\n\n`;
      for (const step of guide.steps) {
        markdown += `<a id="${step.docAnchor}"></a>\n\n## ${t(step.titleKey)}\n\n${t(step.i18nKey)}\n\n`;
        markdown += `[${t("shared.guide.start")}](http://pleey.localhost${step.route}?guide=${guide.id})\n\n`;
        markdown += `![${t(step.titleKey)}](${relative}assets/${guide.id}-${step.anchor}-${locale}.png)\n\n`;
      }
      markdown += `## ${label("facts")}\n\n`;
      for (const [file, key] of [
        ["settings", "settings"],
        ["permissions", "permissions"],
        ["errors", "errors"],
        ["game-types", "types"],
      ])
        markdown += `- [${label(key)}](generated/${file}.md)\n`;
      output.set(prefix + guide.docPath, markdown);
    }
  }
  updateGeneratedUsage(path.join(root, "docs/usage"), output, check);
  return output.size;
}

export function updateGeneratedUsage(usageRoot, output, check) {
  for (const [file, contents] of output) {
    const destination = path.join(usageRoot, file);
    if (check) {
      if (!fs.existsSync(destination) || fs.readFileSync(destination, "utf8") !== contents)
        throw new Error(`Stale generated documentation: ${file}. Run npm run docs:generate in application/frontend.`);
    } else {
      fs.mkdirSync(path.dirname(destination), { recursive: true });
      fs.writeFileSync(destination, contents);
    }
  }
  for (const file of filesUnder(usageRoot).filter((file) => file.endsWith(".md"))) {
    if (fs.readFileSync(file, "utf8").startsWith(generatedNotice) && !output.has(path.relative(usageRoot, file)))
      throw new Error(`Obsolete generated page: ${file}`);
  }
}
if (process.argv[1] && import.meta.url === pathToFileURL(path.resolve(process.argv[1])).href)
  console.log(`Usage reference: ${generateUsageReference(repositoryRoot, process.argv.includes("--check"))} files.`);
